mapper.sql:
select * from walk_ranking
where activity_id = #{activityId}
  and ranking_type = #{rankingType}
and date_format(record_date, '%Y-%m-%d') = #{recordDate}
order by rank_no

mapper.delete:
delete from walk_ranking
where activity_id = #{activityId}
  and ranking_type = #{rankingType}
and date_format(record_date, '%Y-%m-%d') = #{recordDate}
